export const FIELD_PATHS = new Set(SCHEMA.map((r) => r[0]));
// path of every value in a scene, in schema notation (stops[].x, director{id}.keys[].t, ...)
export function fieldPaths(scene) {
  const out = new Set();
  const walk = (v, p) => {
    if (Array.isArray(v)) { if (p === "viewpoints") { out.add("viewpoints[]"); return; } if (/(points|at|stand|move|door)$/.test(p) || /^layoutAdds\[\]\.[ab]$/.test(p)) { out.add(p); return; } out.add(p + "[]"); for (const x of v) walk(x, p + "[]"); return; }
    if (v && typeof v === "object") { if (/(title|text)$/.test(p) && p.includes("caps")) { out.add(p); return; } if (p === "director") { out.add(p); for (const [, x] of Object.entries(v)) walk(x, "director{id}"); return; } if (p) out.add(p); for (const [k, x] of Object.entries(v)) walk(x, p ? p + "." + k : k); return; }
    out.add(p);
  };
  walk(scene, ""); out.delete(""); return out;
}
